// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    ReentrancyDAO c;
    function setUp() public { c = new ReentrancyDAO(); }
    function testFuzz_property(uint256 amount, bool isContract) public {
        amount = bound(amount, 0, 100 ether);
        address caller;
        if (isContract) {
            caller = address(new ZeroValueRejector());
        } else {
            caller = makeAddr("eoa");
        }

        vm.deal(caller, amount);
        vm.prank(caller);
        c.deposit{value: amount}();

        vm.prank(caller);
        c.withdrawAll();

        bool success;
        vm.prank(caller);
        try c.withdrawAll() {
            success = true;
        } catch {
            success = false;
        }
        assertTrue(success);
    }
}

contract ZeroValueRejector {
    receive() external payable {
        require(msg.value > 0, "zero value rejected");
    }
}
